  'feature.calendar.recurring': 'Återkommande lektioner',
  'feature.calendar.recurringDesc': 'Skapa återkommande lektioner varje eller varannan vecka. De visas automatiskt i både din och elevens kalender.',
  'feature.calendar.breaks': 'Paushantering',
  'feature.calendar.breaksDesc': 'Ange automatiska pauser mellan lektionerna så att du inte dubbelbokas utan tid för återhämtning.',
